import workcell
from PIL import Image

def find_bores(path):
    im = Image.open(path)
    w, h = im.size
    px = im.load()
    spots = []
    for y in range(10, h-10):
        for x in range(10, w-10):
            r,g,b = px[x,y][:3]
            if r > 90:
                continue
            if 20 <= r <= 40 and abs(r-g) < 8 and abs(g-b) < 8:
                continue
            s = 0; n = 0
            for dy in (-8, 0, 8):
                for dx in (-8, 0, 8):
                    rr = px[x+dx, y+dy][0]
                    if rr > 80:
                        s += rr; n += 1
            if n >= 3 and s/n - r > 45 and r < 75:
                spots.append((x,y,r))
    clusters = []
    for x,y,r in spots:
        placed=False
        for c in clusters:
            cx=sum(p[0] for p in c)/len(c)
            cy=sum(p[1] for p in c)/len(c)
            if (x-cx)**2+(y-cy)**2 < 18**2:
                c.append((x,y,r)); placed=True; break
        if not placed:
            clusters.append([(x,y,r)])
    out = []
    for c in clusters:
        if len(c) < 6:
            continue
        wsum = sum((90-p[2]) for p in c)
        cx = sum(p[0]*(90-p[2]) for p in c)/wsum
        cy = sum(p[1]*(90-p[2]) for p in c)/wsum
        out.append((round(cx,1), round(cy,1), len(c), min(p[2] for p in c)))
    return out

