        for x in range(20,w-20):
            r=px[x,y][0]
            if r>48: continue
            # skip uniform dark gripper
            if px[x,y][1]<45 and px[x,y][2]<50 and r<40:
                # check if isolated
                neigh_bright=0
                for dy in (-16,16):
                    for dx in (-16,16):
                        if px[x+dx,y+dy][0]>120:
                            neigh_bright+=1
                if neigh_bright<2:
                    continue
            dk.append((x,y,r))
    clusters=[]
    for x,y,r in dk:
        placed=False
        for c in clusters:
            cx=sum(p[0] for p in c)/len(c)
            cy=sum(p[1] for p in c)/len(c)
            if (x-cx)**2+(y-cy)**2<22**2:
